{
  "predictors": [
    {
      "name": "R&D Intensity Momentum",
      "construction": "Calculate the change in R&D expenditure (Compustat item XRD) as a percentage of total assets (Compustat item AT) over the past 3 years.",
      "rationale": "Firms increasing their R&D investments at a faster rate may be positioning for future growth, suggesting management confidence in innovation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Earnings Consistency",
      "construction": "Compute the standard deviation of quarterly earnings (Compustat item EPSPI) over the past 8 quarters.",
      "rationale": "Firms with more consistent earnings are perceived as less risky, which might be undervalued by the market.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Dividend Growth Surprise",
      "construction": "Measure the unexpected growth in dividends by taking the difference between the actual growth rate and the average analyst forecasted growth rate (IBES data) over the past year.",
      "rationale": "Unexpected increases in dividends can signal management's confidence in future cash flows.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Productivity Growth",
      "construction": "Calculate the percentage change in revenue per employee (Compustat item SALE divided by Compustat item EMP) over the past 5 years.",
      "rationale": "Growth in productivity suggests efficient use of labor, which can lead to higher profitability.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Insider Buying Pressure",
      "construction": "Aggregate the ratio of insider purchase transactions to total insider transactions (reported to SEC) over the past year.",
      "rationale": "Increased insider buying suggests confidence in the firm's future prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Count the number of citations received by a firm's patents (USPTO data) normalized by total patents held, over the past 5 years.",
      "rationale": "High-impact patents indicate valuable innovations and potential competitive advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Free Cash Flow Yield",
      "construction": "Calculate free cash flow (Operating Cash Flow minus Capital Expenditures) as a percentage of enterprise value (market capitalization plus total debt) over the trailing 12 months.",
      "rationale": "A higher free cash flow yield may indicate a firm's ability to generate cash relative to its valuation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Tax Efficiency Ratio",
      "construction": "Determine the ratio of net income (Compustat item NI) to pretax income (Compustat item PI) over the last fiscal year.",
      "rationale": "Firms with higher tax efficiency retain more earnings, potentially leading to higher growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Supplier Network Stability",
      "construction": "Assess the change in the number of key suppliers (disclosed in 10-K filings) over the past 3 years.",
      "rationale": "Stability or growth in supplier relationships can indicate a reliable supply chain, reducing operational risks.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Environmental Compliance Trend",
      "construction": "Calculate the annual change in environmental compliance costs (reported in sustainability reports) as a percentage of operating expenses, over the past 5 years.",
      "rationale": "Firms improving environmental compliance may reduce future regulatory risks and enhance reputation.",
      "higher_returns_for": "low values of the measure"
    }
  ]
}
